CREATE OR REPLACE PROCEDURE sp(para_eer_threshold real, para_target_mode text)
LANGUAGE plpgsql
AS $$
DECLARE
    v_ac_record record;
    v_next_id integer;
    v_ac_id integer;
    v_cooling double precision;
    v_heating double precision;
    v_power numeric;
    v_eer numeric;
    v_phase double precision;
    v_flow double precision;
    v_rated_capacity double precision;
    v_theoretical double precision;
    v_capacity_ratio double precision;
    v_actual_efficiency double precision;
    v_actual_cop double precision;
    v_carnot_cop double precision;
    v_total_consumption numeric;
    v_sample_days integer;
    v_avg_indoor numeric;
    v_avg_outdoor numeric;
    v_avg_setting numeric;
    v_setpoint_gap_deficiency boolean;
    v_affected boolean;
    v_factor double precision;
    v_power_multiplier numeric;
    v_annual_emissions numeric;
BEGIN
    DELETE FROM carbon_emissions
     WHERE annual_emissions_tonnes <= 0;

    SELECT COALESCE(MAX(id) + 1, 1)
      INTO v_next_id
      FROM carbon_emissions;

    FOR v_ac_record IN
        SELECT a.ac_id,
               a.manufacturer,
               a.model,
               a.cooling_capacity_btu,
               a.heating_capacity_btu,
               a.power_consumption_watts,
               a.energy_efficiency_ratio,
               a.refrigerant_type,
               r.phase_change_heat_kj_per_kg,
               r.refrigerant_flow_rate_kg_per_s
          FROM air_conditioner_info a
          LEFT JOIN refrigerant_properties r
            ON r.refrigerant_type = a.refrigerant_type
         ORDER BY a.ac_id ASC
    LOOP
        v_ac_id := v_ac_record.ac_id;
        v_cooling := v_ac_record.cooling_capacity_btu::double precision;
        v_heating := v_ac_record.heating_capacity_btu::double precision;
        v_power := v_ac_record.power_consumption_watts;
        v_eer := v_ac_record.energy_efficiency_ratio;
        v_phase := v_ac_record.phase_change_heat_kj_per_kg;
        v_flow := v_ac_record.refrigerant_flow_rate_kg_per_s;

        IF para_target_mode = 'Heating' THEN
            v_rated_capacity := v_heating;
        ELSE
            v_rated_capacity := v_cooling;
        END IF;

        IF v_phase IS NOT NULL AND v_flow IS NOT NULL THEN
            v_theoretical := v_phase * v_flow * 3412.14;

            IF COALESCE(v_rated_capacity, 0.0) = 0.0 THEN
                v_capacity_ratio := NULL;
            ELSE
                v_capacity_ratio := v_theoretical / v_rated_capacity;
            END IF;

            IF COALESCE(v_power, 0) = 0 THEN
                v_actual_efficiency := NULL;
            ELSE
                v_actual_efficiency := v_rated_capacity / v_power::double precision;
            END IF;
        ELSE
            v_capacity_ratio := 1.0;
            v_actual_efficiency := v_eer::double precision;
        END IF;

        IF v_actual_efficiency IS NULL THEN
            v_actual_cop := NULL;
        ELSE
            v_actual_cop := v_actual_efficiency / 3.412;
        END IF;

        SELECT COALESCE(SUM(energy_consumption_kwh), 0),
               COUNT(DISTINCT record_date)::integer,
               AVG(indoor_temperature_celsius),
               AVG(outdoor_temperature_celsius),
               AVG(temperature_setting_celsius)
          INTO v_total_consumption,
               v_sample_days,
               v_avg_indoor,
               v_avg_outdoor,
               v_avg_setting
          FROM energy_consumption
         WHERE ac_id = v_ac_id
           AND mode = para_target_mode;

        v_setpoint_gap_deficiency := false;
        IF v_avg_indoor IS NOT NULL AND v_avg_setting IS NOT NULL THEN
            IF para_target_mode = 'Cooling' THEN
                IF (v_avg_indoor - v_avg_setting) > 2.0 THEN
                    v_setpoint_gap_deficiency := true;
                END IF;
            ELSIF para_target_mode = 'Heating' THEN
                IF (v_avg_setting - v_avg_indoor) > 2.0 THEN
                    v_setpoint_gap_deficiency := true;
                END IF;
            END IF;
        END IF;

        v_carnot_cop := NULL;
        IF v_avg_indoor IS NOT NULL AND v_avg_outdoor IS NOT NULL THEN
            IF v_avg_outdoor > v_avg_indoor THEN
                v_carnot_cop := (v_avg_indoor::double precision + 273.15)
                                / (v_avg_outdoor::double precision - v_avg_indoor::double precision);
            END IF;
        END IF;

        v_affected := false;
        IF v_capacity_ratio IS NOT NULL AND v_capacity_ratio < 0.85 THEN
            v_affected := true;
        END IF;
        IF v_actual_efficiency IS NOT NULL
           AND para_eer_threshold IS NOT NULL
           AND v_actual_efficiency < para_eer_threshold THEN
            v_affected := true;
        END IF;
        IF v_carnot_cop IS NOT NULL
           AND v_actual_cop IS NOT NULL
           AND v_actual_cop < 0.04 * v_carnot_cop THEN
            v_affected := true;
        END IF;
        IF v_setpoint_gap_deficiency THEN
            v_affected := true;
        END IF;

        IF NOT v_affected THEN
            CONTINUE;
        END IF;

        IF v_capacity_ratio IS NOT NULL AND v_capacity_ratio > 0 THEN
            v_factor := 1.0 / v_capacity_ratio;
        ELSE
            v_factor := 1.0;
        END IF;

        UPDATE energy_consumption
           SET energy_consumption_kwh = energy_consumption_kwh * v_factor
         WHERE ac_id = v_ac_id
           AND mode = para_target_mode;

        IF v_capacity_ratio IS NOT NULL AND v_capacity_ratio < 0.85 THEN
            v_power_multiplier := LEAST(1.5::numeric,
                                        1.0::numeric + (1.0::numeric - v_capacity_ratio::numeric));
            v_power := v_power * v_power_multiplier;

            UPDATE air_conditioner_info
               SET power_consumption_watts = power_consumption_watts * v_power_multiplier
             WHERE ac_id = v_ac_id;
        END IF;

        IF v_sample_days > 0 THEN
            v_annual_emissions := (v_total_consumption / v_sample_days) * 365.0 * 0.000233;
        ELSE
            v_annual_emissions := (v_power / 1000.0) * 1000.0 * 0.000233;
        END IF;

        INSERT INTO carbon_emissions (id, emission_factor, annual_emissions_tonnes)
        VALUES (v_next_id, 0.000233, v_annual_emissions);

        v_next_id := v_next_id + 1;
    END LOOP;
END;
$$;
